def fill(g):
    H=len(g); W=len(g[0])
    band=max(range(H), key=lambda i: sum(1 for v in g[i] if v==4))
    # stripe rows = all rows except header rows (rows that are all 1/4 or nearly full)
    out=[r[:] for r in g]
    def rowperiod(row):
        n=0; Wd=W
        for p in range(2,Wd+1):
            ok=True; M={}
            for j,v in enumerate(row):
                if v in (0,4): continue
                kk=(j-n)%p
                if kk in M and M[kk]!=v: ok=False;break
                M[kk]=v
            if ok and len(M)==p: return p,M,n
        return None,None,n
    for i in range(band+1,H):
        pp,M,n=rowperiod(out[i])
        if pp is None: continue
        for j in range(W):
            if out[i][j]==0: out[i][j]=M[(j-n)%pp]
    return out
